@sig trait AP_Availability_Intake_i_Api {
  def id: Art.BridgeId
  def ap_availability_in_Id : Art.PortId
  def ap_availability_out_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var ap_availability_out: FAA_FCS_Coordination.AP_Availability.Type = $

  def put_ap_availability_out(value : FAA_FCS_Coordination.AP_Availability.Type) : Unit = {
    Contract(
      Modifies(ap_availability_out),
      Ensures(
        ap_availability_out == value
      )
    )
    Spec {
      ap_availability_out = value
    }

    Art.putValue(ap_availability_out_Id, FAA_FCS_Coordination.AP_Availability_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class AP_Availability_Intake_i_Initialization_Api (
  val id: Art.BridgeId,
  val ap_availability_in_Id : Art.PortId,
  val ap_availability_out_Id : Art.PortId) extends AP_Availability_Intake_i_Api

@datatype class AP_Availability_Intake_i_Operational_Api (
  val id: Art.BridgeId,
  val ap_availability_in_Id : Art.PortId,
  val ap_availability_out_Id : Art.PortId) extends AP_Availability_Intake_i_Api {

  // Logika spec var representing port state for incoming data port
  @spec var ap_availability_in: FAA_FCS_Coordination.AP_Availability.Type = $

  def get_ap_availability_in() : Option[FAA_FCS_Coordination.AP_Availability.Type] = {
    Contract(
      Ensures(
        Res == Some(ap_availability_in)
      )
    )
    val value : Option[FAA_FCS_Coordination.AP_Availability.Type] = Art.getValue(ap_availability_in_Id) match {
      case Some(FAA_FCS_Coordination.AP_Availability_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port ap_availability_in.  Expecting 'FAA_FCS_Coordination.AP_Availability_Payload' but received ${v}")
        None[FAA_FCS_Coordination.AP_Availability.Type]()
      case _ => None[FAA_FCS_Coordination.AP_Availability.Type]()
    }
    return value
  }
}
